async (page) => {
  const events = [];
  const onErr = e => events.push({type:'pageerror', msg: String(e.message||e)});
  const onCon = m => { if (m.type()==='error') events.push({type:'console', msg: m.text()}); };
  page.on('pageerror', onErr); page.on('console', onCon);
  const btns = page.locator('button');
  const n = await btns.count();
  const out = [];
  for (let i=0;i<n;i++){
    events.length = 0;
    const b = btns.nth(i);
    const label = await b.evaluate(el => (el.closest('section,div,[id]')?.id||'') + ' | ' + (el.closest('section,div')?.innerText||'').slice(0,80));
    await b.click();
    await page.waitForTimeout(2500);
    out.push({i, label, events: [...events]});
  }
  page.off('pageerror', onErr); page.off('console', onCon);
  return out;
}

